package com.school; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import com.school.repository.SubjectRepository; import com.school.model.Subject; import java.util.List; @SpringBootTest public class MongoTest { @Autowired private SubjectRepository subjectRepository; @Test public void test() { List<Subject> subjects = subjectRepository.findAll(); for(Subject s: subjects) { if (s.getLevelNo() != null && s.getLevelNo() == 5 && s.getSemesterNo() != null && s.getSemesterNo() == 2) { System.out.println("FOUND SUBJECT: " + s.getName() + " FOR COURSE: " + (s.getCourse() != null ? s.getCourse().getProgramType() : "null")); } } } }